CREATE EXTENSION IF NOT EXISTS postgis;

DROP TABLE IF EXISTS edge_failure_probability;

CREATE TABLE edge_failure_probability (
    edge_id BIGINT PRIMARY KEY,
    source BIGINT NOT NULL,
    target BIGINT NOT NULL,
    source_layer TEXT NOT NULL,
    is_synthetic BOOLEAN NOT NULL,
    length_m DOUBLE PRECISION NOT NULL,
    epicentral_distance_km DOUBLE PRECISION NOT NULL,
    pgv_cm_s DOUBLE PRECISION NOT NULL,
    repair_rate_per_km DOUBLE PRECISION NOT NULL,
    failure_probability DOUBLE PRECISION NOT NULL CHECK (failure_probability BETWEEN 0 AND 1),
    model_variant TEXT NOT NULL,
    geom geometry(LineString, 4326) NOT NULL
);

BEGIN;
COMMIT;

CREATE INDEX edge_failure_probability_geom_idx ON edge_failure_probability USING GIST (geom);
CREATE INDEX edge_failure_probability_probability_idx ON edge_failure_probability (failure_probability);
